// 「导入我的书」 must chunk and vectorise exactly like scripts/import-library.py + library-vectors.py build.
// - splitPage: edge cases from Python's split_page (fixture regenerated by running split_page on the texts).
// - encodeNpz: readable by parseNpz (np.load compatibility was checked once by hand; see docs/desktop-plan.md).
// - buildVectors: rebuilding a bundled book reproduces its Python vectors.npz (skipped without .local-library).
import { openSealed } from '../../lib/classics/sealed';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fixRadicals } from '../../lib/library-import/pdf-text';
import { splitPage, splitPages } from '../../lib/library-import/split';
import { buildVectors, overlappingTexts } from '../../lib/vectors/build';
import { VECTOR_DIMENSIONS } from '../../lib/vectors/encoder';
import { encodeNpz, parseNpz } from '../../lib/vectors/npy';
import { getEncoder } from '../../lib/vectors/search';

const cases: { text: string; chunks: string[] }[] = JSON.parse(
  readFileSync(join(__dirname, 'fixtures/split-page-python.json'), 'utf8'));
for (const { text, chunks } of cases) assert.deepEqual(splitPage(text), chunks, JSON.stringify(text.slice(0, 40)));
assert.deepEqual(splitPages(['甲。', '', '乙。']), [{ page: 1, text: '甲。' }, { page: 3, text: '乙。' }]);
assert.equal(fixRadicals('⽯泉⼭⼈⽈：⽃数，⽥宅。⼦⼥！'), '石泉山人曰：斗数，田宅。子女！');
console.log(`PASS split-page: ${cases.length} cases identical to Python`);

assert.deepEqual(overlappingTexts([
  { page: 1, text: '第一句。第二句；' },
  { page: 1, text: '下一段' },
  { page: 2, text: '换页' },
  { page: 2, text: '无标点' },
]), ['第一句。第二句；', '第二句；下一段', '换页', '换页无标点']);

const vectors = new Float32Array(3 * VECTOR_DIMENSIONS).map((_, i) => Math.sin(i));
const archive = parseNpz(encodeNpz({
  source_sha256: { dtype: 'unicode', width: 64, value: 'a'.repeat(64) },
  vectors: { dtype: 'float32', shape: [3, VECTOR_DIMENSIONS], data: vectors },
}));
assert.deepEqual(archive.get('source_sha256'), { dtype: 'unicode', shape: [], data: ['a'.repeat(64)] });
assert.deepEqual(archive.get('vectors'), { dtype: 'float32', shape: [3, VECTOR_DIMENSIONS], data: vectors });
console.log('PASS npz-writer: round trip');

const library = join(process.cwd(), '.local-library');
const book = join(library, 'books', 'b4629e9002dbc6f7d08e5854'); // smallest bundled book, 55 chunks
if (!existsSync(join(library, 'taiwei-model/model.onnx')) || !existsSync(join(book, 'vectors.npz'))) {
  console.log('SKIP vector-build: .local-library not found');
  process.exit(0);
}
(async () => {
  // 从书库包解出来的书正文是加密的，先解开（lib/classics/sealed.ts）。
  const raw = JSON.parse(readFileSync(join(book, 'book.json'), 'utf8')) as { chunks?: { page: number; text: string }[]; sealed?: string };
  const chunks: { page: number; text: string }[] = raw.sealed ? JSON.parse(openSealed(raw.sealed)) : raw.chunks!;
  const python = parseNpz(readFileSync(join(book, 'vectors.npz'))).get('vectors');
  assert.equal(python?.dtype, 'float32');
  const encoder = await getEncoder(join(library, 'taiwei-model'));
  const built = await buildVectors(encoder, overlappingTexts(chunks));
  assert.equal(built.length, (python!.data as Float32Array).length);
  let worst = 1;
  for (let row = 0; row < chunks.length; row++) {
    let dot = 0;
    for (let i = 0; i < VECTOR_DIMENSIONS; i++) dot += built[row * VECTOR_DIMENSIONS + i] * (python!.data as Float32Array)[row * VECTOR_DIMENSIONS + i];
    worst = Math.min(worst, dot);
  }
  assert.ok(worst >= 0.9999, `min cosine ${worst}`);
  console.log(`PASS vector-build: ${chunks.length} vectors match Python build, min cosine ${worst.toFixed(7)}`);
})();
